(window.webpackJsonp=window.webpackJsonp||[]).push([[25],{462:function(n,e,r){n.exports=r.p+"assets/img/image-20260824152340704.e0c11197.png"},490:function(n,e,r){"use strict";r.r(e);var t=r(25),a=Object(t.a)({},(function(){var n=this,e=n._self._c;return e("ContentSlotsDistributor",{attrs:{"slot-key":n.$parent.slotKey}},[e("h1",{attrs:{id:"_5-mutipoint-一次绘多个点"}},[e("a",{staticClass:"header-anchor",attrs:{href:"#_5-mutipoint-一次绘多个点"}},[n._v("#")]),n._v(" 5/mutiPoint 一次绘多个点")]),n._v(" "),e("p",[e("img",{attrs:{src:r(462),alt:"image-20260824152340704"}})]),n._v(" "),e("blockquote",[e("p",[n._v("[!tip]")]),n._v(" "),e("p",[n._v('缓存区就只是一段连续的内存，存原始数值。没有"结构"，没有类型信息，没有字段名——就是一个字节数组。缓冲区本身不懂自己存的是什么，是后面的 '),e("code",[n._v("vertexAttribPointer")]),n._v(" 告诉它怎么解读：")])]),n._v(" "),e("div",{staticClass:"language- extra-class"},[e("pre",{pre:!0,attrs:{class:"language-text"}},[e("code",[n._v('缓冲区里的原始字节              vertexAttribPointer 告诉你怎么读\n┌─────────────────────────────┐\n│ 0.0 | 0.5 | -0.5 | -0.5 ... │  ← 对缓冲区来说，就是一堆字节\n└─────────────────────────────┘        没有"x"、没有"y"、没有"顶点"的概念\n\nvertexAttribPointer(\n    a_Position, 2, gl.FLOAT, false, 0, 0\n    └────┘   └─┘   └─────┘      └─┘└─┘\n    哪个变量  几个  什么类型  步长 偏移\n                  一组\n)\n')])])]),e("div",{staticClass:"language- extra-class"},[e("pre",{pre:!0,attrs:{class:"language-text"}},[e("code",[n._v("/**\n * Create a program object and make current\n * @param gl GL context\n * @param vshader a vertex shader program (string)\n * @param fshader a fragment shader program (string)\n * @return true, if the program object was created and successfully made current \n */\nfunction initShaders(gl, vshader, fshader) {\n  var program = createProgram(gl, vshader, fshader);\n  if (!program) {\n    console.log('Failed to create program');\n    return false;\n  }\n\n  gl.useProgram(program);\n  gl.program = program;\n\n  return true;\n}\n\n/**\n * Create the linked program object\n * @param gl GL context\n * @param vshader a vertex shader program (string)\n * @param fshader a fragment shader program (string)\n * @return created program object, or null if the creation has failed\n */\nfunction createProgram(gl, vshader, fshader) {\n  // Create shader object\n  var vertexShader = loadShader(gl, gl.VERTEX_SHADER, vshader);\n  var fragmentShader = loadShader(gl, gl.FRAGMENT_SHADER, fshader);\n  if (!vertexShader || !fragmentShader) {\n    return null;\n  }\n\n  // Create a program object\n  var program = gl.createProgram();\n  if (!program) {\n    return null;\n  }\n\n  // Attach the shader objects\n  gl.attachShader(program, vertexShader);\n  gl.attachShader(program, fragmentShader);\n\n  // Link the program object\n  gl.linkProgram(program);\n\n  // Check the result of linking\n  var linked = gl.getProgramParameter(program, gl.LINK_STATUS);\n  if (!linked) {\n    var error = gl.getProgramInfoLog(program);\n    console.log('Failed to link program: ' + error);\n    gl.deleteProgram(program);\n    gl.deleteShader(fragmentShader);\n    gl.deleteShader(vertexShader);\n    return null;\n  }\n  return program;\n}\n\n/**\n * Create a shader object\n * @param gl GL context\n * @param type the type of the shader object to be created\n * @param source shader program (string)\n * @return created shader object, or null if the creation has failed.\n */\nfunction loadShader(gl, type, source) {\n  // Create shader object\n  var shader = gl.createShader(type);\n  if (shader == null) {\n    console.log('unable to create shader');\n    return null;\n  }\n\n  // Set the shader program\n  gl.shaderSource(shader, source);\n\n  // Compile the shader\n  gl.compileShader(shader);\n\n  // Check the result of compilation\n  var compiled = gl.getShaderParameter(shader, gl.COMPILE_STATUS);\n  if (!compiled) {\n    var error = gl.getShaderInfoLog(shader);\n    console.log('Failed to compile shader: ' + error);\n    gl.deleteShader(shader);\n    return null;\n  }\n\n  return shader;\n}\n\n\nfunction initWebGL(canvas) {\n  const dpr = window.devicePixelRatio || 1;\n  console.log(dpr);\n  canvas.width = 400 * dpr;\n  canvas.height = 300 * dpr;\n  canvas.style.width = '400px';\n  canvas.style.height = '300px'\n\n  const gl = canvas.getContext('webgl');\n  if (!gl) {\n    console.error('Failed to get WebGL context');\n    return null;\n  }\n  gl.viewport(0, 0, canvas.width, canvas.height);\n  gl.clearColor(0, 0, 0, 1);\n  return gl;\n}\n\nwindow.onload = function(){\n\n    /*\n        着色器是申明attribute变量\n        attribute变量赋值给gl_Position\n        向attribute变量传递变量\n     */\n    //顶点着色器程序\n    var VSHADER_SOURCE = \n    'attribute vec4 a_Position;\\n'+ \n    'void main(){\\n'+\n    ' gl_Position = a_Position;\\n'+\n    ' gl_PointSize = 10.0;\\n'+\n    '}\\n';\n\n    // //片元着色器\n    var FSHADER_SOURCE =  \n    'void main(){\\n'+\n    ' gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0);\\n'+\n    '}\\n';\n \n\n    var canvas = document.getElementById('webgl')\n    var gl = initWebGL(canvas)\n    if(!gl){\n        console.log('Failed to get thd rendering context for webgl')\n        return;\n    }\n\n    //初始着色器\n    if(!initShaders(gl,VSHADER_SOURCE,FSHADER_SOURCE)){\n        console.log('failed to initialize shaders')\n        return;\n    }\n\n    //设置顶点位置\n    var n = initVertexBuffers(gl)\n    if(n<0){\n        console.log('failed to set the position of the vertices')\n        return;\n    }\n     //设置<canvas>背景色\n    gl.clearColor(0.0,0.0,0.0,1.0);\n\n    // //清空<canvas>\n    gl.clear(gl.COLOR_BUFFER_BIT)\n\n    // //绘制三个点\n    gl.drawArrays(gl.POINTS,0,n)\n\n    /*\n    使用缓冲区对象向顶点着色器传入多个顶点的数据 五步骤\n    1.创建缓冲区对象 (gl.createBuffer())。\n    2.绑定缓冲区对象(gl.bindBuffer())。\n    3.将数据写人缓冲区对象(gl.bufferData())。\n    4.将缓冲区对象分配给一个attribute变量(gl.vertexAttribPointer())\n    5.开启attribute变量(gl.enableVertexAttribArray())。*/\n    function initVertexBuffers(gl){\n        var vertices = new Float32Array([\n            0.0,0.5,-0.5,-0.5,0.5,-0.5\n        ]) \n        var n = 3;\n\n        //1创建缓存区对象\n        var vertexBuffer = gl.createBuffer();\n        if(!vertexBuffer){\n            console.log('failed to create the buffer object');\n            return -1;\n        }\n\n        //2将缓存区对象绑定到目标。这个“目标”表示缓冲区对象的用途（在这里，就是向顶点着色器提供传给attribute变量的数据)，这样WebGL才能够正确处理其中的内容。\n        //gl.ARRAY_BUFFER表示缓冲区对象中包含了顶点的索引值 \n        gl.bindBuffer(gl.ARRAY_BUFFER,vertexBuffer)\n\n        //3向缓存区对象中写入数据\n        //该方法的效果是，将第2个参数vertices中的数据写入了绑定到第1个参数gl.ARRAY_BUFFER上的缓冲区对象。\n        //不能直接向缓冲区写入数据，而只能向“目标\"写人数据，所以要向缓冲区写数据，必须先绑定。 \n        gl.bufferData(gl.ARRAY_BUFFER,vertices,gl.STATIC_DRAW);\n\n        var a_Position = gl.getAttribLocation(gl.program,'a_Position');\n        if(a_Position < 0){\n            console.log('failed to get the storage location of a_Position')\n        }  \n\n        //4、分配 将缓存区对象分配给a_Position变量\n        gl.vertexAttribPointer(a_Position,2,gl.FLOAT,false,0,0);\n\n       /* \n        vertexAttribPointer(\n            location,    // 哪个 attribute 变量\n            size,        // 每个顶点有几个分量（x,y → 2个）\n            type,        // 数据类型（浮点数）\n            normalized,  // 是否归一化（整数类型才有意义）\n            stride,      // 步长（相邻顶点之间隔多少字节）\n            offset       // 偏移（从哪个字节开始读第一个顶点）\n        )\n\n        参数\t值\t含义\n        location\ta_Position\t着色器里的 a_Position 变量\n        size\t2\t每个顶点有 2个分量（x, y）\n        type\tgl.FLOAT\t数据是浮点数\n        normalized\tfalse\t不做归一化处理\n        stride\t0\t顶点之间紧密排列，无间隔（0表示自动计算）\n        offset\t0\t从第 0 个字节开始读取\n        */\n\n        //5、连接 连接a_Position变量与分配给它的缓存区对象 （打开这个 attribute 变量的数据流开关。）\n        //enableVertexAttribArray 是一个使能开关，告诉 WebGL：渲染时请从这个 attribute 关联的缓冲区读取数据，而不是使用默认的固定值。\n        gl.enableVertexAttribArray(a_Position);\n\n        return n;\n\n    }\n\n/*\n第1步：找个盘子（创建缓冲区）\n第2步：把盘子放在桌上（绑定）\n第3步：把菜放进去（写入数据）\n第4步：告诉厨师\"这盘菜怎么吃\"（描述布局）\n第5步：把菜推到厨师面前（开启数据流）\n1212121\n*/ \n\n\n   \n    \n\n}\n")])])])])}),[],!1,null,null,null);e.default=a.exports}}]);